import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Gamepad2, ArrowLeft, Eye, EyeOff } from "lucide-react";
import "./App.css";

export default function Login({ onSuccess }) {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);

  const handleLogin = (e) => {
    e.preventDefault();
    if (onSuccess) onSuccess(); 
    navigate("/dashboard");
  };

  return (
    <div className="auth-container">
      {/* LEFT SIDE: Teal Theme (Matches your 1st picture) */}
      <div className="auth-left teal-theme">
        <div className="auth-brand">
          <Gamepad2 size={32} /> VidyaQuest
        </div>
        
        <h1 className="auth-title">
          Continue Your <br/> Learning Adventure!
        </h1>
        
        <p className="auth-desc">
          Pick up where you left off. Your progress, badges, and achievements are waiting for you.
        </p>
       
        {/* Stats Row */}
        <div className="stats-mini-row" style={{ marginTop: '2rem' }}>
           <div className="mini-stat">
             <strong style={{fontSize:'1.5rem'}}>500+</strong>
             <span style={{fontSize:'0.85rem'}}>Active Learners</span>
           </div>
           <div className="mini-stat">
             <strong style={{fontSize:'1.5rem'}}>10K+</strong>
             <span style={{fontSize:'0.85rem'}}>Lessons Done</span>
           </div>
        </div>
      </div>

      {/* RIGHT SIDE: Form */}
      <div className="auth-right">
        {/* Back Link */}
        <div style={{ width: '100%', maxWidth: '400px', marginBottom: '2rem' }}>
            <div className="back-link" onClick={() => navigate("/")}>
                <ArrowLeft size={16} /> Back to Home
            </div>
        </div>

        <div className="auth-form-box">
          <h2>Welcome Back!</h2>
          <p className="form-sub">Sign in to continue your learning adventure</p>

          <form onSubmit={handleLogin}>
              <label>Email</label>
              <input type="email" placeholder="your@email.com" className="input-field" required />

              <label>Password</label>
              <div style={{position:'relative'}}>
                 <input 
                    type={showPassword ? "text" : "password"} 
                    placeholder="........" 
                    className="input-field" 
                    required 
                 />
                 <div 
                    onClick={() => setShowPassword(!showPassword)}
                    style={{
                        position:'absolute', 
                        right:'15px', 
                        top:'14px', 
                        cursor:'pointer',
                        color: '#94a3b8'
                    }}
                 >
                    {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                 </div>
              </div>
             
              <div style={{textAlign:'right', fontSize:'0.9rem', color:'#0d9488', marginTop:'10px', cursor:'pointer', fontWeight:'600'}}>
                  Forgot Password?
              </div>

              {/* Teal Button to match theme */}
              <button type="submit" className="btn-auth btn-teal">
                  Sign In
              </button>
          </form>

          <div className="auth-link" style={{marginTop: '1.5rem', textAlign: 'center'}}>
            Don't have an account? <span style={{color: '#0d9488', fontWeight: 'bold', cursor: 'pointer'}} onClick={() => navigate("/signup")}>Sign Up</span>
          </div>
        </div>
      </div>
    </div>
  );
}
